import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.vLhlLNVn.js";const i="/assets/assistent-einheit.Yyq_lvKl.png",f=JSON.parse('{"title":"Sources, units and signs","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/01.quellen-und-einheiten.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","filePath":"adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md"};function s(d,e,u,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sources-units-and-signs" tabindex="-1">Sources, units and signs <a class="header-anchor" href="#sources-units-and-signs" aria-label="Permalink to &quot;Sources, units and signs&quot;">​</a></h1><p><a id="separate-import-feed-one-datapoint"></a></p><h2 id="how-do-i-separate-consumption-from-the-grid-and-feed-in-one-datapoint-with-a-sign" tabindex="-1">How do I separate consumption from the grid and feed-in (one datapoint with a sign)? <a class="header-anchor" href="#how-do-i-separate-consumption-from-the-grid-and-feed-in-one-datapoint-with-a-sign" aria-label="Permalink to &quot;How do I separate consumption from the grid and feed-in (one datapoint with a sign)?&quot;">​</a></h2><p>With two sources, because SourceAnalytix does not evaluate the sign. The first uses the datapoint for grid import, the second an alias with the sign flipped for feed-in. Both get &quot;Ignore negative values&quot;.</p><ol><li>On the &quot;Price definitions&quot; tab, create two prices in <code>kWh</code>: <code>Grid import</code> with cost type &quot;Costs&quot; and <code>Feed-in</code> with cost type &quot;Earnings&quot;. For feed-in, the &quot;Price per unit&quot; is your feed-in tariff per kWh.</li><li>On the &quot;Objects&quot; tab, create an alias on the power datapoint that flips the sign (<code>-val</code>), with the unit <code>W</code>.</li><li>Use &quot;Add source&quot; to create a source for the original datapoint with type &quot;Power&quot; and the price <code>Grid import</code>.</li><li>Create a source for the alias in the same way, with the price <code>Feed-in</code>.</li><li>For both, set &quot;Ignore negative values&quot; in the detail view under &quot;Settings&quot; and click &quot;⚡ Apply&quot;.</li></ol><p>Grid import then appears under <code>currentYear.consumed</code>, feed-in under <code>currentYear.delivered</code> and the earnings under <code>currentYear.earnings</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Without &quot;Ignore negative values&quot;, feed-in pulls the import total down. The daily consumption then only shows the balance and can turn negative.</p></div><p>If your electricity meter has separate readings for import and feed-in, use those as two meter-reading sources instead. That is more accurate.</p><p><strong>See also:</strong> <a href="#track-pv-yield-feed-earnings">PV yield, feed-in and earnings</a> · <a href="./preise-und-kosten#assign-prices-create-custom-tariffs">How do I assign prices?</a></p><p><a id="unit-datapoint-kwh-wh-m3"></a></p><h2 id="which-unit-do-i-set-on-the-datapoint-kwh-instead-of-wh-m3-instead-of-liters" tabindex="-1">Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)? <a class="header-anchor" href="#which-unit-do-i-set-on-the-datapoint-kwh-instead-of-wh-m3-instead-of-liters" aria-label="Permalink to &quot;Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)?&quot;">​</a></h2><p>The unit the datapoint really delivers. The wizard usually detects it itself (&quot;Detected from the datapoint: …&quot;). The price definition decides which unit you see the values in. SourceAnalytix converts from Wh to kWh or from l to m³ on its own.</p><p><img src="'+i+'" alt="The wizard&#39;s &quot;Unit&quot; step with &quot;Detected from the datapoint&quot;"></p><p>Typical mistakes:</p><ul><li><strong>Meter reading labelled <code>W</code>:</strong> the value is summed up over time and becomes absurdly high. Choose <code>Wh</code> or <code>kWh</code>.</li><li><strong>Power labelled <code>kWh</code>:</strong> every value counts as a meter reading. Choose <code>W</code> or <code>kW</code>.</li><li><strong><code>Wh</code> and <code>kWh</code> mixed up:</strong> everything is off by a factor of 1,000.</li></ul><p>If SourceAnalytix detects no unit, the &quot;Problems&quot; tab reports &quot;Unit missing or not recognised&quot;. Use &quot;Fix&quot; to choose it.</p><h3 id="why-kwh-appears-instead-of-m3" tabindex="-1">Why kWh appears instead of m³ <a class="header-anchor" href="#why-kwh-appears-instead-of-m3" aria-label="Permalink to &quot;Why kWh appears instead of m³&quot;">​</a></h3><p>The chosen price definition uses <code>kWh</code>. Create a separate gas price in <code>m³</code> and choose it for the source. SourceAnalytix does not convert cubic metres of gas into kWh; if the units don&#39;t match, you can&#39;t choose the price at all.</p><h3 id="if-you-change-the-unit-later" tabindex="-1">If you change the unit later <a class="header-anchor" href="#if-you-change-the-unit-later" aria-label="Permalink to &quot;If you change the unit later&quot;">​</a></h3><p>SourceAnalytix does not convert stored values. If you switch to a price whose unit differs from the stored data, say from kWh to MWh, the source does not start. The &quot;Problems&quot; tab then shows &quot;The price definition uses another unit than the stored data&quot;. Choose a price in the old unit, or delete the source&#39;s data and start over.</p><p>If the unit on the datapoint was wrong, say Wh instead of kWh, the new one applies from the next value. Afterwards, correct the total and the periods with &quot;Align meter reading&quot;, see <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Which units are supported?</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Start values and their unit</a></p><p><a id="sourceanalytix-compute-consumption-meter-reading"></a></p><h2 id="can-sourceanalytix-calculate-consumption-and-a-meter-reading-from-power-w" tabindex="-1">Can SourceAnalytix calculate consumption and a meter reading from power (W)? <a class="header-anchor" href="#can-sourceanalytix-calculate-consumption-and-a-meter-reading-from-power-w" aria-label="Permalink to &quot;Can SourceAnalytix calculate consumption and a meter reading from power (W)?&quot;">​</a></h2><p>Yes. SourceAnalytix multiplies each power value by the time until the next one and adds that to its own total. This gives consumption and costs in the energy unit of the price definition, for example kWh.</p><p>The total starts at 0 on activation, so it is not your electricity meter&#39;s reading. How accurate it is depends on how often the device sends. You don&#39;t need start values or reset detection.</p><p>In the wizard, choose the type &quot;Power&quot; and a price in <code>Wh</code>, <code>kWh</code> or <code>MWh</code>. The power options are described under <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">If you only have a power value</a>. With &quot;Align meter reading&quot; you can match the total to a real meter; after that the two drift apart again.</p><p><strong>See also:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a> · <a href="./../referenz/einstellungen#source-types-exist-meter-power">Which source types are there?</a></p><p><a id="track-pv-yield-feed-earnings"></a></p><h2 id="how-do-i-track-pv-yield-feed-in-and-earnings" tabindex="-1">How do I track PV yield, feed-in and earnings? <a class="header-anchor" href="#how-do-i-track-pv-yield-feed-in-and-earnings" aria-label="Permalink to &quot;How do I track PV yield, feed-in and earnings?&quot;">​</a></h2><p>Each meter becomes its own source with a price of cost type &quot;Earnings&quot;. SourceAnalytix then writes delivery and earnings instead of consumption and costs.</p><table tabindex="0"><thead><tr><th>What</th><th>Datapoint</th><th>Price definition</th></tr></thead><tbody><tr><td>PV yield</td><td>the inverter&#39;s total yield in kWh</td><td>&quot;Earnings&quot;; without money, leave &quot;Costs&quot; off</td></tr><tr><td>Feed-in and earnings</td><td>the feed-in register of the electricity meter</td><td>&quot;Earnings&quot;, price = feed-in tariff</td></tr><tr><td>Grid import</td><td>the import register of the electricity meter</td><td>&quot;Costs&quot;</td></tr></tbody></table><p>Use the total yield, not &quot;yield today&quot;, which drops to 0 every night. The values are under <code>currentYear.delivered</code> and <code>currentYear.earnings</code>, and in the detail view as &quot;Delivery&quot; and &quot;Earnings&quot;. SourceAnalytix does not calculate self-consumption or self-sufficiency.</p><p><strong>See also:</strong> <a href="#separate-import-feed-one-datapoint">Import and feed-in from one datapoint</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Start values</a></p><p><a id="derive-counter-flow-run-time"></a></p><h2 id="how-do-i-derive-a-counter-from-flow-rate-run-time-or-several-devices" tabindex="-1">How do I derive a counter from flow rate, run time or several devices? <a class="header-anchor" href="#how-do-i-derive-a-counter-from-flow-rate-run-time-or-several-devices" aria-label="Permalink to &quot;How do I derive a counter from flow rate, run time or several devices?&quot;">​</a></h2><p>With a script. SourceAnalytix evaluates each datapoint on its own and only sums power and pulses per minute over time. For everything else, a script writes a rising meter reading in a supported unit, and you activate that datapoint.</p><table tabindex="0"><thead><tr><th>Case</th><th>What you do</th></tr></thead><tbody><tr><td>Several phases</td><td>use the device&#39;s total counter, otherwise sum the phases in a script</td></tr><tr><td>Several devices</td><td>one source per device; a script builds a sum</td></tr><tr><td>Flow rate (<code>m³/h</code>, <code>l/min</code>)</td><td>a script adds rate × time to <code>m³</code> or <code>l</code></td></tr><tr><td>Burner run time</td><td>a script calculates run time × consumption per hour in <code>l</code> or <code>kWh</code></td></tr><tr><td>Burner starts</td><td>directly as a meter reading with unit <code>piece</code></td></tr><tr><td>Fill level (oil tank)</td><td>a script only sums the decreases, without refills</td></tr></tbody></table><p>Cleanest is a sum that never falls: the script only adds the increase of each sub-meter and ignores decreases. If the sum does fall, reset detection handles it like for any meter.</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Which units are supported?</a> · <a href="#use-script-datapoints-unreliable-sources">Script datapoints</a></p><p><a id="use-script-datapoints-unreliable-sources"></a></p><h2 id="can-i-use-script-datapoints-or-unreliable-sources" tabindex="-1">Can I use script datapoints or unreliable sources? <a class="header-anchor" href="#can-i-use-script-datapoints-or-unreliable-sources" aria-label="Permalink to &quot;Can I use script datapoints or unreliable sources?&quot;">​</a></h2><p>Yes. Any datapoint can be a source, whether an adapter, a script, an alias or Simple-API writes it. It has to deliver a number in a supported unit; text such as <code>&quot;12,5&quot;</code> works too.</p><ul><li>Give the datapoint the type number and a unit, for example <code>kWh</code>. The wizard then lists it under &quot;Matching datapoints&quot;.</li><li>Write a meter reading that only goes up.</li><li>If a value is not a number, the &quot;Problems&quot; tab reports &quot;Datapoint delivers text instead of a number&quot;.</li></ul><p>Only reset detection filters outliers: small drops up to the &quot;Threshold&quot; and a brief 0 are ignored. A jump upwards counts as consumption right away. If your source sometimes delivers absurdly high values, filter them in a script first.</p><p>You set how many decimals SourceAnalytix outputs for the source under &quot;For experts&quot;.</p><p><strong>See also:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean?</a> · <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a></p>',47)])])}const m=t(n,[["render",s]]);export{f as __pageData,m as default};
